// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.junit.jupiter.api.Test;

class KernelTermKindProofTest {

	@Test
	void directTermKindProofPreservesUnknownAndErrorPossibilities() {
		int literal = 1 << ValueIds.TERM_KIND_LITERAL;
		KernelTermKindProof proof = KernelTermKindProof.forKind(0, literal);

		assertEquals(KernelTermKindProof.TRUE_BIT, proof.evaluate(ignored -> literal));
		assertEquals(KernelTermKindProof.FALSE_BIT,
				proof.evaluate(ignored -> 1 << ValueIds.TERM_KIND_IRI));
		assertEquals(KernelTermKindProof.ALL_OUTCOMES,
				proof.evaluate(ignored -> 1 << ValueIds.TERM_KIND_UNKNOWN));
		assertEquals(KernelTermKindProof.ALL_OUTCOMES,
				proof.evaluate(ignored -> 1 << ValueIds.TERM_KIND_POINTER));
	}

	@Test
	void composedProofUsesSparqlThreeValuedBooleanRules() {
		int literal = 1 << ValueIds.TERM_KIND_LITERAL;
		int iri = 1 << ValueIds.TERM_KIND_IRI;
		KernelTermKindProof literalProof = KernelTermKindProof.forKind(0, literal);
		KernelTermKindProof iriProof = KernelTermKindProof.forKind(1, iri);

		assertEquals(KernelTermKindProof.FALSE_BIT,
				KernelTermKindProof.and(literalProof, iriProof).evaluate(index -> index == 0 ? iri : literal));
		assertEquals(KernelTermKindProof.TRUE_BIT,
				KernelTermKindProof.or(literalProof, iriProof).evaluate(index -> index == 0 ? literal : literal));
		assertEquals(KernelTermKindProof.ALL_OUTCOMES,
				KernelTermKindProof.not(KernelTermKindProof.unknown()).evaluate(ignored -> literal));
	}

	@Test
	void idMasksRecognizeStoredTermsAndWidenUnknownOrSyntheticIds() {
		assertEquals(1 << ValueIds.TERM_KIND_IRI,
				KernelTermKindProof.maskForId(ValueIds.createId(ValueIds.T_URI, 1L)));
		assertEquals(1 << ValueIds.TERM_KIND_LITERAL,
				KernelTermKindProof.maskForId(ValueIds.createId(ValueIds.T_LITERAL, 1L)));
		assertEquals(KernelTermKindProof.ALL_TERM_KINDS, KernelTermKindProof.maskForId(-1L));
		assertEquals(KernelTermKindProof.ALL_TERM_KINDS, KernelTermKindProof.maskForId(0L));
		assertEquals(KernelTermKindProof.ALL_TERM_KINDS,
				KernelTermKindProof.maskForId(Long.MIN_VALUE + 1024L));
		assertEquals(KernelTermKindProof.ALL_TERM_KINDS,
				KernelTermKindProof.maskForId(ValueIds.createId(ValueIds.T_URI, 1L), true));
	}

	@Test
	void proofFactoriesValidateAndSerializeDeterministically() {
		KernelTermKindProof proof = KernelTermKindProof.not(KernelTermKindProof.and(
				KernelTermKindProof.forKind(0, 1 << ValueIds.TERM_KIND_LITERAL),
				KernelTermKindProof.forKind(1, 1 << ValueIds.TERM_KIND_IRI)));

		assertEquals("not(and(kind(0,0x4),kind(1,0x2)))", proof.canonicalKey());
		assertEquals(
				"org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelTermKindProof.not("
						+ "org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelTermKindProof.and("
						+ "org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelTermKindProof.forKind(0,0x4),"
						+ "org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelTermKindProof.forKind(1,0x2)))",
				proof.javaExpression());
		assertThrows(IllegalArgumentException.class, () -> KernelTermKindProof.forKind(-1, 0));
		assertThrows(IllegalArgumentException.class,
				() -> KernelTermKindProof.forKind(0, 1 << (ValueIds.TERM_KIND_POINTER + 1)));
	}
}
